fn is_palindrome(text: Vec<char>) -> bool {
    // Helper function to convert ASCII uppercase letter to lowercase
    fn to_ascii_lowercase(c: char) -> char {
        if c >= 'A' && c <= 'Z' {
            // Convert uppercase ASCII to lowercase by adding 32 to the byte value
            ((c as u8) + 32) as char
        } else {
            c
        }
    }

    let len = text.len();
    if len == 0 {
        return true; // Empty text is a palindrome by definition
    }

    let mut left = 0;
    let mut right = len - 1;

    while left < right {
        let left_char = to_ascii_lowercase(text[left]);
        let right_char = to_ascii_lowercase(text[right]);

        if left_char != right_char {
            return false;
        }

        left += 1;
        right = right.saturating_sub(1);
    }

    true
}